const QUANT_CONCEPTS = [{"topic": "Order of Operations (PEMDAS)", "category": "Arithmetic", "content": "Evaluate Parentheses, Exponents, Multiplication/Division (left to right), then Addition/Subtraction (left to right).", "ex": "2 + 3 x (4 - 1)^2 = 2 + 3x9 = 29"}, {"topic": "Divisibility Rules", "category": "Arithmetic", "content": "Divisible by 3 if the digit sum is divisible by 3; by 9 if the digit sum is divisible by 9; by 4 if the last two digits are divisible by 4.", "ex": "714: digit sum is 12, so it's divisible by 3 but not by 9."}, {"topic": "Prime Numbers", "category": "Arithmetic", "content": "A prime number has exactly two positive divisors: 1 and itself. 2 is the only even prime.", "ex": "2, 3, 5, 7, 11, 13, 17, 19, 23..."}, {"topic": "LCM and GCF", "category": "Arithmetic", "content": "LCM: smallest number divisible by all given numbers. GCF: largest number that divides all given numbers.", "ex": "LCM(4,6) = 12; GCF(4,6) = 2"}, {"topic": "Fraction-Decimal-Percent Conversion", "category": "Arithmetic", "content": "Percent = fraction x 100. To convert a fraction to a decimal, divide the numerator by the denominator.", "ex": "3/8 = 0.375 = 37.5%"}, {"topic": "Percent Change", "category": "Arithmetic", "content": "Percent change = (New - Old) / Old x 100.", "ex": "Price rises from $80 to $100: change = 20/80 = 25%"}, {"topic": "Ratios and Proportions", "category": "Arithmetic", "content": "A ratio compares two quantities; cross-multiply to solve proportions.", "ex": "If a/b = c/d, then a x d = b x c"}, {"topic": "Exponent Rules", "category": "Arithmetic", "content": "x^a times x^b = x^(a+b); x^a / x^b = x^(a-b); (x^a)^b = x^(ab); x^0 = 1.", "ex": "2^3 x 2^4 = 2^7 = 128"}, {"topic": "Roots and Radicals", "category": "Arithmetic", "content": "sqrt(a x b) = sqrt(a) x sqrt(b). Simplify by factoring out perfect squares.", "ex": "sqrt(72) = sqrt(36 x 2) = 6 x sqrt(2)"}, {"topic": "Absolute Value", "category": "Arithmetic", "content": "|x| represents distance from zero on the number line; always non-negative.", "ex": "|-7| = 7, |7| = 7"}, {"topic": "Solving Linear Equations", "category": "Algebra", "content": "Isolate the variable using inverse operations, keeping both sides balanced.", "ex": "3x + 5 = 20, so x = 5"}, {"topic": "Solving Systems of Equations", "category": "Algebra", "content": "Use substitution or elimination to solve for two unknowns from two equations.", "ex": "x+y=10, x-y=2 gives x=6, y=4"}, {"topic": "Quadratic Formula", "category": "Algebra", "content": "For ax^2+bx+c=0, x = (-b +/- sqrt(b^2-4ac)) / 2a.", "ex": "x^2 - 5x + 6 = 0 gives x = 2 or x = 3"}, {"topic": "Factoring Quadratics", "category": "Algebra", "content": "Look for two numbers that multiply to c and add to b.", "ex": "x^2 + 7x + 12 = (x+3)(x+4)"}, {"topic": "Inequalities", "category": "Algebra", "content": "Flip the inequality sign when multiplying or dividing by a negative number.", "ex": "-2x > 6 gives x < -3"}, {"topic": "Functions and Function Notation", "category": "Algebra", "content": "f(x) describes the output for a given input x; evaluate by substitution.", "ex": "f(x) = 2x+1, so f(3) = 7"}, {"topic": "Sequences", "category": "Algebra", "content": "Arithmetic sequences have a constant difference between terms; geometric sequences have a constant ratio.", "ex": "3,7,11,15 is arithmetic (d=4); 2,6,18,54 is geometric (r=3)"}, {"topic": "Simplifying Algebraic Expressions", "category": "Algebra", "content": "Combine like terms and distribute carefully before solving.", "ex": "3(x+2) - 4x = 3x + 6 - 4x = -x + 6"}, {"topic": "Translating Word Problems", "category": "Algebra", "content": "Identify the unknown, assign a variable, and translate phrases into operations.", "ex": "'5 more than twice a number' becomes 2x + 5"}, {"topic": "Direct and Inverse Variation", "category": "Algebra", "content": "Direct: y = kx (y increases as x increases). Inverse: y = k/x (y decreases as x increases).", "ex": "If y varies inversely with x and y=4 when x=3, then k=12"}, {"topic": "Triangle Angle Sum", "category": "Geometry", "content": "The interior angles of any triangle sum to 180 degrees.", "ex": "If two angles are 50 and 60 degrees, the third is 70 degrees."}, {"topic": "Pythagorean Theorem", "category": "Geometry", "content": "For a right triangle, a^2 + b^2 = c^2, where c is the hypotenuse.", "ex": "A 3-4-5 triangle satisfies 3^2 + 4^2 = 5^2"}, {"topic": "Special Right Triangles", "category": "Geometry", "content": "45-45-90 triangles have sides in ratio 1:1:sqrt(2). 30-60-90 triangles have sides in ratio 1:sqrt(3):2.", "ex": "In a 30-60-90 triangle with shortest side 5, the hypotenuse is 10."}, {"topic": "Area and Perimeter Basics", "category": "Geometry", "content": "Rectangle: A=lw, P=2(l+w). Triangle: A=(1/2)bh. Circle: A=pi r^2, C=2 pi r.", "ex": "A circle with r=4 has area 16 pi."}, {"topic": "Volume and Surface Area of Solids", "category": "Geometry", "content": "Rectangular solid: V=lwh. Cylinder: V=pi r^2 h. Sphere: V=(4/3) pi r^3.", "ex": "A cylinder with r=3, h=10 has V=90 pi."}, {"topic": "Similar Triangles", "category": "Geometry", "content": "Similar triangles have equal corresponding angles and proportional sides.", "ex": "If triangle ABC ~ DEF with ratio 2:1, all of DEF's sides are half of ABC's."}, {"topic": "Circles: Arcs and Sectors", "category": "Geometry", "content": "Arc length = (angle/360) x 2 pi r. Sector area = (angle/360) x pi r^2.", "ex": "A 90-degree sector of a circle with r=4 has area 4 pi."}, {"topic": "Coordinate Geometry: Slope and Distance", "category": "Geometry", "content": "Slope = (y2-y1)/(x2-x1). Distance = sqrt((x2-x1)^2 + (y2-y1)^2).", "ex": "The slope between (1,2) and (4,8) is 6/3 = 2."}, {"topic": "Equation of a Line", "category": "Geometry", "content": "Slope-intercept form: y = mx + b, where m is the slope and b is the y-intercept.", "ex": "A line through (0,3) with slope 2 is y = 2x + 3."}, {"topic": "Parallel and Perpendicular Lines", "category": "Geometry", "content": "Parallel lines have equal slopes; perpendicular lines have slopes that are negative reciprocals.", "ex": "A line with slope 2 is perpendicular to one with slope -1/2."}, {"topic": "Polygon Interior Angle Sum", "category": "Geometry", "content": "Sum of interior angles = (n-2) x 180 degrees, where n is the number of sides.", "ex": "A hexagon (n=6) has an interior angle sum of 720 degrees."}, {"topic": "Quadrilateral Properties", "category": "Geometry", "content": "Parallelograms have opposite sides equal and parallel; rectangles add right angles; rhombi add equal sides.", "ex": "A rectangle's diagonals are equal in length and bisect each other."}, {"topic": "Mean, Median, and Mode", "category": "Data Analysis", "content": "Mean: sum divided by count. Median: middle value when ordered. Mode: most frequent value.", "ex": "For {2,3,3,7,10}: mean=5, median=3, mode=3."}, {"topic": "Range and Standard Deviation", "category": "Data Analysis", "content": "Range = max - min. Standard deviation measures the spread of data around the mean.", "ex": "For {4,8,6,5,3}: range = 8-3 = 5."}, {"topic": "Probability Basics", "category": "Data Analysis", "content": "Probability = favorable outcomes / total outcomes, always between 0 and 1.", "ex": "Probability of rolling a 4 on a fair die = 1/6."}, {"topic": "Independent and Dependent Events", "category": "Data Analysis", "content": "For independent events, P(A and B) = P(A) x P(B); dependent events need conditional probability.", "ex": "P(two heads in a row) = 1/2 x 1/2 = 1/4."}, {"topic": "Permutations vs. Combinations", "category": "Data Analysis", "content": "Permutations count order-dependent arrangements (nPr); combinations count order-independent selections (nCr).", "ex": "Choosing 2 from 5 people: C(5,2)=10; ordering them: P(5,2)=20."}, {"topic": "Counting Principle", "category": "Data Analysis", "content": "If one event can occur m ways and another n ways, together they can occur m x n ways.", "ex": "3 shirts x 4 pants = 12 outfit combinations."}, {"topic": "Reading Data Tables and Graphs", "category": "Data Analysis", "content": "Check axis labels, units, and scale carefully before interpreting a graph or table.", "ex": "A bar reaching '40' on a chart scaled in thousands represents 40,000."}, {"topic": "Weighted Averages", "category": "Data Analysis", "content": "Weighted average accounts for the relative frequency or importance of each value.", "ex": "20 students average 80 and 10 average 90: weighted average = (20x80+10x90)/30, about 83.3."}, {"topic": "Percentile and Quartiles", "category": "Data Analysis", "content": "Percentiles divide data into 100 equal parts; quartiles divide it into 4 (Q1, Q2=median, Q3).", "ex": "A score at the 90th percentile beats 90% of test-takers."}, {"topic": "Set Theory: Union and Intersection", "category": "Data Analysis", "content": "Union (A union B) combines all elements; intersection (A intersect B) includes only shared elements.", "ex": "|A union B| = |A| + |B| - |A intersect B|"}, {"topic": "Estimation and Approximation", "category": "Data Analysis", "content": "Round values strategically to estimate quickly, especially useful without a calculator.", "ex": "398 x 21 is about 400 x 20 = 8,000"}, {"topic": "Rate Problems", "category": "Data Analysis", "content": "Distance = rate x time. Combined work rate = 1/time1 + 1/time2.", "ex": "A car traveling 60 mph for 2.5 hours covers 150 miles."}, {"topic": "Quantitative Comparison Strategy", "category": "Data Analysis", "content": "Compare Quantity A and Quantity B directly; test multiple values (negatives, fractions, zero) before assuming a relationship always holds.", "ex": "If x^2=9, Quantity A=x is not necessarily greater than Quantity B=0, since x could be -3."}];

const VERBAL_QUESTIONS = [{"type": "text-completion", "passage": null, "prompt": "Despite the committee's ______ efforts to reach a consensus, the meeting ended in the same deadlock as before.", "choices": ["desultory", "assiduous", "indolent", "cursory", "perfunctory"], "correct": [1], "explanation": "\"Despite\" signals a contrast between the effort and the outcome. \"Assiduous\" (showing great care and perseverance) fits a genuine, diligent effort that still failed to produce results; the other choices describe careless or half-hearted effort, which would not create the needed contrast."}, {"type": "text-completion", "passage": null, "prompt": "The critic's review was anything but ______; it dissected the film's flaws with unsparing precision.", "choices": ["laudatory", "trenchant", "scathing", "vitriolic", "acerbic"], "correct": [0], "explanation": "\"Anything but\" means the blank is the opposite of what follows. Since the review harshly picked apart the film's flaws, it was not \"laudatory\" (praising). The other options all describe harsh criticism, which is what the sentence says the review WAS, not what it was NOT."}, {"type": "text-completion", "passage": null, "prompt": "Far from being ______, the new intern quickly grasped complex financial models that stumped seasoned analysts.", "choices": ["precocious", "obtuse", "erudite", "sagacious", "astute"], "correct": [1], "explanation": "\"Far from being\" signals the blank should describe a negative trait contradicted by the rest of the sentence. Quickly understanding complex material is the opposite of being \"obtuse\" (slow to understand). The remaining choices are all positive traits, which wouldn't need to be negated by \"far from.\""}, {"type": "text-completion", "passage": null, "prompt": "The senator's speech was praised for its ______, distilling a complicated policy into just a few clear sentences.", "choices": ["verbosity", "brevity", "loquacity", "prolixity", "garrulity"], "correct": [1], "explanation": "\"Brevity\" means concise, exact use of words, matching \"distilling...into just a few clear sentences.\" The other four choices are all synonyms for excessive wordiness, the opposite of what's praised here."}, {"type": "text-completion", "passage": null, "prompt": "Because the professor's lectures were so ______, students often found themselves confused about the exam material despite attending every class.", "choices": ["lucid", "obfuscatory", "cogent", "articulate", "coherent"], "correct": [1], "explanation": "\"Because\" signals a supporting relationship: the cause of the students' confusion must be the lectures' lack of clarity. \"Obfuscatory\" means tending to make things unclear, which explains the confusion; the other choices all describe clear, well-organized lectures."}, {"type": "text-completion", "passage": null, "prompt": "The novel's plot, while engaging, relies on several ______ coincidences that strain credulity.", "choices": ["fortuitous", "contrived", "plausible", "organic", "subtle"], "correct": [1], "explanation": "\"Strain credulity\" means the coincidences are hard to believe, which fits \"contrived\" (artificially arranged rather than natural). \"Fortuitous\" just means happening by chance without the negative connotation of being forced, and the remaining options suggest believability, the opposite of what's needed."}, {"type": "text-completion", "passage": null, "prompt": "Rather than confronting the issue directly, the manager chose a ______ approach, hinting at problems without ever naming them.", "choices": ["forthright", "oblique", "candid", "direct", "blunt"], "correct": [1], "explanation": "\"Rather than confronting...directly\" sets up a contrast with directness. \"Oblique\" means indirect, matching \"hinting at problems without ever naming them.\" The other four choices all mean direct or honest, the opposite of the intended meaning."}, {"type": "text-completion", "passage": null, "prompt": "The old professor's lectures, though famously ______, were also unexpectedly popular; students packed the hall despite the three-hour length.", "choices": ["concise", "prolix", "succinct", "terse", "laconic"], "correct": [1], "explanation": "The clue \"despite the three-hour length\" tells us the lectures were long-winded. \"Prolix\" means using more words than needed, or long-winded, which matches. The other four choices all mean the opposite: brief and to the point."}, {"type": "text-completion", "passage": null, "prompt": "The evidence against the defendant was so ______ that even his own lawyer struggled to construct a defense.", "choices": ["equivocal", "incontrovertible", "circumstantial", "tenuous", "dubious"], "correct": [1], "explanation": "If even the defense lawyer struggled to argue against the evidence, the evidence must be extremely strong and undeniable. \"Incontrovertible\" means not able to be denied or disputed. The other choices all suggest weak or questionable evidence, which would make the lawyer's task easier, not harder."}, {"type": "text-completion", "passage": null, "prompt": "Her ______ manner in the boardroom belied the nervous energy she felt inside.", "choices": ["turbulent", "placid", "frenetic", "agitated", "volatile"], "correct": [1], "explanation": "\"Belied\" means gave a false impression of, so her outward manner must contrast with her inner \"nervous energy.\" \"Placid\" (calm) creates that contrast. The other four choices all describe agitation, which would match rather than contradict her inner state."}, {"type": "text-completion", "passage": null, "prompt": "The critic accused the memoir of being needlessly ______, padded with tangents that added nothing to the narrative.", "choices": ["succinct", "digressive", "economical", "spare", "terse"], "correct": [1], "explanation": "\"Padded with tangents\" directly describes wandering off the main topic, which is the meaning of \"digressive.\" The other four choices all mean concise or economical with words, the opposite of being padded with tangents."}, {"type": "text-completion", "passage": null, "prompt": "Environmental scientists warn that the chemical runoff could have a ______ effect on the local fish population, slowly poisoning the water supply over decades.", "choices": ["transient", "negligible", "pernicious", "benign", "salubrious"], "correct": [2], "explanation": "\"Slowly poisoning...over decades\" describes a gradually harmful effect, matching \"pernicious\" (harmful, especially in a gradual or subtle way). The other choices describe effects that are brief, minor, harmless, or even beneficial, none of which fit \"slowly poisoning.\""}, {"type": "text-completion", "passage": null, "prompt": "Unlike his predecessor, who ruled through fear, the new manager took a ______ approach, seeking input from every team member before major decisions.", "choices": ["autocratic", "collaborative", "despotic", "imperious", "tyrannical"], "correct": [1], "explanation": "\"Unlike his predecessor, who ruled through fear\" sets up a contrast with an authoritarian style. \"Collaborative\" (seeking input from others) is the clear opposite and matches \"seeking input from every team member.\" The other four choices all describe forms of authoritarian rule."}, {"type": "text-completion", "passage": null, "prompt": "The company's ______ growth over just two years, from a small startup to an industry leader, stunned even its own founders.", "choices": ["gradual", "meteoric", "incremental", "sluggish", "stagnant"], "correct": [1], "explanation": "\"From a small startup to an industry leader\" in \"just two years\" describes extremely rapid growth. \"Meteoric\" means rapid and dramatic, like a meteor streaking across the sky. The other choices all describe slow or absent growth."}, {"type": "text-completion", "passage": null, "prompt": "The mayor's ______ promises to cut taxes while increasing city services drew skepticism from budget analysts.", "choices": ["contradictory", "consistent", "feasible", "modest", "realistic"], "correct": [0], "explanation": "Cutting taxes while increasing services are two goals in tension with each other, which analysts would view skeptically. \"Contradictory\" captures that internal tension. The other choices describe promises that would be easy to believe, not ones that would draw skepticism."}, {"type": "sentence-equivalence", "passage": null, "prompt": "The lecture was so ______ that half the audience left before it ended.", "choices": ["tedious", "riveting", "interminable", "captivating", "mundane", "enthralling"], "correct": [0, 2], "explanation": "The blank must explain why people left early: the lecture was boring and felt like it dragged on. \"Tedious\" and \"interminable\" (seemingly endless) both capture that sense, producing equivalent sentences. The other choices describe an engaging or merely ordinary lecture, which wouldn't explain the walkout."}, {"type": "sentence-equivalence", "passage": null, "prompt": "Her arguments were so ______ that even her harshest critics found themselves nodding in agreement.", "choices": ["cogent", "fallacious", "convoluted", "dubious", "compelling", "meandering"], "correct": [0, 4], "explanation": "The blank must describe arguments strong enough to win over critics. \"Cogent\" and \"compelling\" both mean forcefully convincing, giving equivalent sentences. The other choices describe weak, confusing, or questionable arguments, which wouldn't persuade harsh critics."}, {"type": "sentence-equivalence", "passage": null, "prompt": "The old bridge was deemed ______, and engineers recommended it be closed to traffic immediately.", "choices": ["sturdy", "precarious", "impregnable", "robust", "unstable", "reliable"], "correct": [1, 4], "explanation": "Closing the bridge to traffic implies it was unsafe. \"Precarious\" and \"unstable\" both describe a structure at risk of failing, producing equivalent sentences. The remaining choices all describe a strong, safe bridge, which wouldn't warrant closure."}, {"type": "sentence-equivalence", "passage": null, "prompt": "Despite his wealth, he lived a remarkably ______ life, avoiding all extravagance.", "choices": ["austere", "opulent", "profligate", "lavish", "spartan", "ostentatious"], "correct": [0, 4], "explanation": "\"Avoiding all extravagance\" despite wealth describes a simple, unadorned lifestyle. \"Austere\" and \"spartan\" both mean severely simple, giving equivalent sentences. The other choices describe lavish or wasteful living, the opposite of what's described."}, {"type": "sentence-equivalence", "passage": null, "prompt": "The scientist's hypothesis, once considered ______, is now widely accepted by the research community.", "choices": ["heterodox", "orthodox", "commonplace", "conventional", "unorthodox", "mainstream"], "correct": [0, 4], "explanation": "\"Once considered ___, is now widely accepted\" implies the hypothesis used to be seen as unconventional or fringe. \"Heterodox\" and \"unorthodox\" both mean departing from accepted beliefs, giving equivalent sentences. The remaining choices all describe ideas that were already standard, which contradicts \"now widely accepted\" as a change."}, {"type": "sentence-equivalence", "passage": null, "prompt": "The politician's promises turned out to be entirely ______, with none of them fulfilled after the election.", "choices": ["empty", "substantive", "hollow", "concrete", "meaningful", "genuine"], "correct": [0, 2], "explanation": "Promises with \"none of them fulfilled\" were essentially worthless. \"Empty\" and \"hollow\" both describe promises lacking real substance, giving equivalent sentences. The other choices describe promises that had real substance, which contradicts the outcome described."}, {"type": "sentence-equivalence", "passage": null, "prompt": "The professor's explanation was so ______ that even graduate students struggled to follow it.", "choices": ["lucid", "abstruse", "transparent", "recondite", "straightforward", "simple"], "correct": [1, 3], "explanation": "If graduate students struggled to follow the explanation, it must have been very difficult to understand. \"Abstruse\" and \"recondite\" both mean difficult to understand, giving equivalent sentences. The remaining choices all describe an explanation that is easy to follow, the opposite of the situation described."}, {"type": "sentence-equivalence", "passage": null, "prompt": "Rather than confronting the problem, the CEO chose to ______ it, hoping it would resolve itself.", "choices": ["address", "ignore", "confront", "overlook", "tackle", "resolve"], "correct": [1, 3], "explanation": "\"Rather than confronting\" signals the blank should mean the opposite of dealing with the problem directly. \"Ignore\" and \"overlook\" both mean to fail to address something, giving equivalent sentences. The other choices all mean to deal with the problem directly, which contradicts \"rather than confronting.\""}, {"type": "sentence-equivalence", "passage": null, "prompt": "The critic praised the novel's ______ prose, noting that not a single word felt wasted.", "choices": ["verbose", "economical", "spare", "prolix", "florid", "ornate"], "correct": [1, 2], "explanation": "\"Not a single word felt wasted\" describes writing that is efficient and unadorned. \"Economical\" and \"spare\" both describe concise, efficient prose, giving equivalent sentences. The remaining choices describe wordy or elaborately decorated prose, the opposite of the praise being described."}, {"type": "sentence-equivalence", "passage": null, "prompt": "The negotiations remained ______ for months, with neither side willing to budge an inch.", "choices": ["fluid", "intransigent", "flexible", "deadlocked", "stalemated", "amicable"], "correct": [3, 4], "explanation": "\"Neither side willing to budge\" describes negotiations that have reached an impasse. \"Deadlocked\" and \"stalemated\" both describe a standstill with no progress, giving equivalent sentences. The other choices describe negotiations that are flexible or friendly, which contradicts the described rigidity."}, {"type": "sentence-equivalence", "passage": null, "prompt": "His ______ remarks at the funeral brought comfort to the grieving family.", "choices": ["consoling", "callous", "comforting", "insensitive", "curt", "brusque"], "correct": [0, 2], "explanation": "Remarks that \"brought comfort\" must have been kind and soothing. \"Consoling\" and \"comforting\" both mean offering comfort, giving equivalent sentences. The remaining choices describe unkind or curt remarks, which would not comfort a grieving family."}, {"type": "sentence-equivalence", "passage": null, "prompt": "The committee's decision seemed entirely ______, based on no discernible criteria.", "choices": ["arbitrary", "systematic", "capricious", "methodical", "principled", "rigorous"], "correct": [0, 2], "explanation": "\"Based on no discernible criteria\" describes a decision made at random, without reasoned justification. \"Arbitrary\" and \"capricious\" both mean based on random choice rather than reason, giving equivalent sentences. The remaining choices describe decisions grounded in clear method or principle, the opposite of what's described."}, {"type": "sentence-equivalence", "passage": null, "prompt": "Years of drought had left the once-fertile valley completely ______.", "choices": ["barren", "verdant", "arid", "lush", "fecund", "flourishing"], "correct": [0, 2], "explanation": "A once-fertile valley ruined by drought would become dry and unproductive. \"Barren\" and \"arid\" both describe land that is dry and unable to support growth, giving equivalent sentences. The remaining choices describe lush, fertile land, the opposite of drought damage."}, {"type": "sentence-equivalence", "passage": null, "prompt": "The young diplomat's ______ handling of the crisis impressed veterans who had expected a misstep.", "choices": ["inept", "adroit", "clumsy", "deft", "bungling", "maladroit"], "correct": [1, 3], "explanation": "Impressing veterans who expected failure implies the handling was skillful. \"Adroit\" and \"deft\" both mean skillful and clever, giving equivalent sentences. The remaining choices all describe clumsy, incompetent handling, which would have confirmed rather than defied expectations."}, {"type": "sentence-equivalence", "passage": null, "prompt": "The reclusive author was famously ______, rarely granting interviews or public appearances.", "choices": ["gregarious", "taciturn", "outgoing", "reticent", "sociable", "convivial"], "correct": [1, 3], "explanation": "\"Rarely granting interviews or public appearances\" describes someone who avoids sharing or being seen. \"Taciturn\" and \"reticent\" both describe a reluctance to speak or reveal oneself publicly, giving equivalent sentences. The remaining choices describe sociable, outgoing behavior, the opposite of reclusiveness."}, {"type": "reading-comprehension", "passage": "Coral reefs, though they occupy less than one percent of the ocean floor, support roughly a quarter of all marine species. This disproportionate biodiversity arises from the structural complexity reefs provide: their nooks and crevices offer shelter, breeding grounds, and hunting territory for organisms ranging from microscopic plankton to apex predators. When rising sea temperatures trigger coral bleaching, the loss extends far beyond the coral itself, unraveling an entire web of dependent life.", "prompt": "The passage suggests that coral bleaching is particularly damaging because", "choices": ["coral reefs are the largest ecosystems on Earth", "coral provides the primary food source for most ocean species", "the structural role reefs play supports far more species than their size would suggest", "bleaching events have become more frequent in recent decades", "coral reefs are located primarily in tropical waters"], "correct": [2], "explanation": "The passage explains that reefs support a disproportionate share of marine biodiversity relative to their small size, because of the structural shelter they provide. This means bleaching harms far more than the coral itself. Choice (C) captures this; the other choices are not stated or supported by the passage."}, {"type": "reading-comprehension", "passage": "Early twentieth-century economists largely assumed that individuals make decisions by rationally weighing costs and benefits. Behavioral economics has since complicated this picture, demonstrating that cognitive biases, such as the tendency to weigh potential losses more heavily than equivalent gains, systematically shape real-world choices. Rather than discarding rational-choice models entirely, most contemporary economists now treat rationality as a useful approximation that must be adjusted for predictable psychological patterns.", "prompt": "The passage implies that contemporary economists regard rational-choice models as", "choices": ["entirely obsolete", "accurate only in laboratory settings", "a rough approximation requiring adjustment", "more reliable than behavioral models", "irrelevant to real-world decision-making"], "correct": [2], "explanation": "The final sentence states that economists treat rationality as \"a useful approximation that must be adjusted,\" directly supporting choice (C). The passage explicitly says the models are not discarded (ruling out A and E), and makes no claim about laboratory settings or comparing reliability to behavioral models."}, {"type": "reading-comprehension", "passage": "The Bronze Age collapse, which swept across the eastern Mediterranean around 1200 BCE, remains one of history's most debated calamities. No single cause, drought, invasion, earthquake, or internal revolt, fully accounts for the near-simultaneous fall of multiple advanced civilizations. Many historians now favor a 'systems collapse' explanation, in which several stresses combined, each amplifying the others until the interconnected trade networks that sustained these societies could no longer function.", "prompt": "According to the passage, the 'systems collapse' explanation is favored because it", "choices": ["identifies drought as the primary cause", "accounts for how multiple factors interacted to overwhelm interdependent societies", "proves that invasion alone destroyed the civilizations", "shows that the civilizations were not actually interconnected", "has been definitively confirmed by archaeological evidence"], "correct": [1], "explanation": "The passage describes the systems collapse theory as multiple stresses combining and amplifying each other until interconnected trade networks failed, matching choice (B). The passage explicitly rejects any single cause (ruling out A and C) and emphasizes interconnection, not its absence (ruling out D)."}, {"type": "reading-comprehension", "passage": "Although octopuses lack the long developmental period and social learning associated with intelligence in mammals, they display remarkable problem-solving abilities, including tool use and the capacity to navigate complex mazes. Neuroscientists have noted that unlike mammalian brains, which centralize most neural processing, roughly two-thirds of an octopus's neurons reside in its arms, suggesting a fundamentally different architecture for cognition.", "prompt": "The passage primarily suggests that octopus intelligence", "choices": ["is inferior to mammalian intelligence", "arises from a distributed, decentralized neural structure unlike that of mammals", "depends on prolonged social learning", "is identical in mechanism to mammalian intelligence", "cannot be measured using standard tests"], "correct": [1], "explanation": "The passage highlights that most of an octopus's neurons are in its arms rather than centralized, calling this \"a fundamentally different architecture for cognition,\" which matches choice (B). The passage explicitly says octopuses lack the long development and social learning of mammals (ruling out C), without claiming inferiority or an identical mechanism."}, {"type": "reading-comprehension", "passage": "Urban planners have increasingly turned to 'road diets,' reducing the number of travel lanes on a street to make room for bike lanes, wider sidewalks, or medians. Critics initially predicted that such changes would worsen traffic congestion. However, studies of implemented road diets have generally found that traffic flow adapts, with minimal impact on overall travel times, while pedestrian and cyclist safety improves measurably.", "prompt": "The passage indicates that the critics' prediction about road diets was", "choices": ["confirmed by subsequent studies", "largely not borne out by evidence", "irrelevant to the debate", "based on pedestrian safety data", "supported by traffic engineers"], "correct": [1], "explanation": "The passage states that studies found \"minimal impact on overall travel times,\" contradicting the critics' prediction of worsened congestion. This matches choice (B). The passage does not say the prediction was confirmed, and it does not describe the critics' prediction as based on safety data."}, {"type": "reading-comprehension", "passage": "The placebo effect, long dismissed as a mere nuisance in clinical trials, has become a subject of serious scientific inquiry in its own right. Researchers have found that placebo responses can trigger measurable physiological changes, including the release of endogenous painkillers, and that the strength of the effect can depend on factors as subtle as the color of a pill or the perceived cost of a treatment.", "prompt": "The passage suggests that attitudes toward the placebo effect have", "choices": ["remained unchanged since it was first documented", "shifted from viewing it as a nuisance to treating it as a legitimate object of study", "become more dismissive over time", "been proven entirely psychological with no physiological basis", "focused exclusively on pill color"], "correct": [1], "explanation": "The first sentence explicitly contrasts the placebo effect being \"long dismissed as a mere nuisance\" with its now being \"a subject of serious scientific inquiry,\" matching choice (B). The passage also notes measurable physiological changes, ruling out (D)."}, {"type": "reading-comprehension", "passage": "Permafrost, ground that remains frozen for at least two consecutive years, underlies roughly a quarter of the Northern Hemisphere's land area. As global temperatures rise, thawing permafrost threatens to release vast stores of trapped carbon and methane, potentially accelerating the very warming that caused the thaw. This feedback loop has prompted scientists to treat permafrost stability as a critical, if underappreciated, factor in climate models.", "prompt": "The passage describes the relationship between permafrost thaw and climate warming as", "choices": ["unrelated", "a one-way process with no feedback", "a self-reinforcing cycle", "fully reversible", "primarily caused by methane alone"], "correct": [2], "explanation": "The passage explicitly calls this a \"feedback loop,\" where thawing releases gases that accelerate the warming that caused the thaw in the first place, matching choice (C), a self-reinforcing cycle. This directly contradicts choice (B)."}, {"type": "reading-comprehension", "passage": "The gig economy is often celebrated for offering workers flexibility, yet this flexibility carries tradeoffs. Independent contractors typically forgo employer-sponsored benefits, unemployment insurance, and the collective bargaining power afforded to traditional employees. Some economists argue that the apparent freedom of gig work masks a shift of risk from companies onto individual workers, who must now absorb costs once borne by employers.", "prompt": "The passage suggests that some economists view the flexibility of gig work as", "choices": ["an unambiguous benefit for all workers", "accompanied by a transfer of risk from companies to individuals", "equivalent to traditional employment protections", "irrelevant to discussions of worker risk", "the primary cause of unemployment insurance"], "correct": [1], "explanation": "The final sentence states that the flexibility \"masks a shift of risk from companies onto individual workers,\" directly supporting choice (B). The passage explicitly notes the tradeoffs, contradicting the idea of an \"unambiguous benefit\" (A) or equivalence to traditional protections (C)."}, {"type": "reading-comprehension", "passage": "Although Impressionist painters are now celebrated for their innovative use of light and color, their early exhibitions were met with derision from established critics, who viewed the loose brushwork as unfinished and amateurish. It was only decades later, as changing aesthetic sensibilities took hold, that the movement was reappraised as a serious and influential artistic development.", "prompt": "The passage indicates that critical reception of Impressionism", "choices": ["was consistently positive from the outset", "changed substantially over time", "remained hostile even after the movement gained influence", "was shaped primarily by the artists themselves", "had no bearing on the movement's later reputation"], "correct": [1], "explanation": "The passage contrasts early derision with later celebration, describing a reappraisal \"decades later.\" This shift over time matches choice (B); it directly contradicts choices (A) and (C)."}, {"type": "reading-comprehension", "passage": "Microplastics, fragments smaller than five millimeters, have been detected in ocean water, soil, and even human blood. While research into their health effects remains in early stages, scientists have expressed particular concern about their capacity to adsorb and transport other pollutants, potentially delivering concentrated toxins to organisms that ingest them.", "prompt": "According to the passage, a specific concern about microplastics is that they may", "choices": ["dissolve harmlessly in ocean water", "serve as vehicles for delivering other pollutants to organisms", "be too large to be ingested by most organisms", "have been thoroughly studied with conclusive results", "exist only in ocean environments"], "correct": [1], "explanation": "The passage states scientists are concerned about microplastics' \"capacity to adsorb and transport other pollutants, potentially delivering concentrated toxins,\" matching choice (B). The passage also notes microplastics appear in soil and blood, not only oceans (ruling out E), and says research is in \"early stages\" (ruling out D)."}, {"type": "reading-comprehension", "passage": "Historians of science have long debated whether major discoveries arise from individual genius or from the gradual accumulation of a field's collective knowledge, which makes a discovery 'ripe' for the taking regardless of who makes it. The phenomenon of simultaneous, independent discovery, as when Newton and Leibniz each developed calculus around the same time, lends some support to the latter view.", "prompt": "The example of Newton and Leibniz is used in the passage to", "choices": ["prove that Newton's contributions were more significant", "support the idea that discoveries emerge from a field's accumulated knowledge rather than individual genius alone", "demonstrate that calculus was discovered by accident", "show that scientific collaboration was common in their era", "argue that individual genius is irrelevant to scientific progress"], "correct": [1], "explanation": "The passage says the example \"lends some support\" to the view that discoveries come from accumulated collective knowledge rather than individual genius, matching choice (B). It does not claim collaboration occurred (they worked independently) or that genius is entirely irrelevant."}, {"type": "reading-comprehension", "passage": "Noise pollution, though less visible than other forms of environmental degradation, has measurable effects on wildlife. Many species rely on acoustic signals for mating, navigation, and predator avoidance; chronic exposure to human-generated noise can mask these signals, forcing animals to alter their behavior or abandon otherwise suitable habitats.", "prompt": "The passage suggests that noise pollution primarily harms wildlife by", "choices": ["directly poisoning animals", "interfering with the acoustic signals animals depend on", "destroying physical habitat", "being more visible than other pollutants", "affecting only aquatic species"], "correct": [1], "explanation": "The passage explains that noise \"can mask\" the acoustic signals animals rely on for mating, navigation, and predator avoidance, matching choice (B). It explicitly calls noise pollution \"less visible\" (ruling out D) and does not mention poisoning or destruction of physical habitat."}, {"type": "reading-comprehension", "passage": "The rise of open-access publishing has aimed to remove paywalls that restrict scientific research to those with institutional subscriptions. Proponents argue this democratizes knowledge, while critics note that many open-access models shift costs onto researchers themselves through publication fees, potentially disadvantaging scholars at under-resourced institutions.", "prompt": "The passage indicates that a criticism of open-access publishing is that it", "choices": ["eliminates all costs associated with publishing", "may create a new financial barrier for researchers with limited resources", "has been universally rejected by scientists", "restricts access to research even further", "applies only to well-funded institutions"], "correct": [1], "explanation": "The passage states that critics note publication fees can \"disadvantage scholars at under-resourced institutions,\" matching choice (B). It does not say costs are eliminated (A) or that access is restricted further (D); open-access is about removing reader paywalls, not adding them."}, {"type": "reading-comprehension", "passage": "Contrary to the popular image of the solitary genius, historical analyses of scientific breakthroughs frequently reveal extensive networks of correspondence, rivalry, and collaboration behind seemingly individual achievements. Even Darwin, often cast as a lone naturalist, corresponded with hundreds of colleagues and relied heavily on specimens and observations gathered by others.", "prompt": "The passage uses the example of Darwin to", "choices": ["challenge the notion that scientific achievement is typically the product of isolated individual work", "argue that Darwin's theories were incorrect", "show that Darwin worked entirely alone", "prove that collaboration guarantees scientific success", "suggest that Darwin's contemporaries were more important than he was"], "correct": [0], "explanation": "The passage opens by challenging \"the popular image of the solitary genius,\" then uses Darwin as an example of someone who relied on an extensive network, directly supporting choice (A). This is the opposite of choice (C)."}, {"type": "reading-comprehension", "passage": "Water scarcity is often framed as a problem of absolute supply, yet in many regions the more pressing issue is distribution and management. Countries with ample freshwater resources can still experience severe shortages due to inefficient irrigation, aging infrastructure, or political disputes over allocation, while regions with comparatively modest supplies sometimes manage water scarcity effectively through careful policy.", "prompt": "The passage suggests that water scarcity is", "choices": ["always caused by insufficient natural supply", "sometimes more a matter of management and distribution than raw supply", "unrelated to infrastructure or policy", "more severe in resource-rich countries than resource-poor ones without exception", "impossible to manage through policy"], "correct": [1], "explanation": "The passage's main point is that scarcity is \"often framed as a problem of absolute supply\" but is \"more pressing\" as an issue of \"distribution and management,\" matching choice (B). The examples given directly contradict choice (A) and choice (E)."}];

const QUANT_QUESTIONS = [{"type": "problem-solving", "data": null, "prompt": "If 3x + 7 = 22, what is the value of x?", "choices": ["3", "5", "7", "9", "15"], "correct": [1], "explanation": "Subtract 7 from both sides: 3x = 15. Divide by 3: x = 5."}, {"type": "problem-solving", "data": null, "prompt": "A store marks up the price of an item by 25% and then offers a 20% discount on the marked-up price. What is the net percent change from the original price?", "choices": ["-5%", "0%", "5%", "10%", "-10%"], "correct": [1], "explanation": "The combined multiplier is 1.25 x 0.80 = 1.00, meaning the final price equals the original price: a 0% net change. This is a common trap, since 25% - 20% = 5% is NOT how percent changes combine."}, {"type": "problem-solving", "data": null, "prompt": "What is the greatest common factor of 84 and 126?", "choices": ["6", "14", "21", "42", "63"], "correct": [3], "explanation": "84 = 2^2 x 3 x 7 and 126 = 2 x 3^2 x 7. The GCF takes the lowest power of each shared prime: 2 x 3 x 7 = 42."}, {"type": "problem-solving", "data": null, "prompt": "If the ratio of boys to girls in a class is 3:5 and there are 40 students total, how many girls are there?", "choices": ["15", "20", "24", "25", "30"], "correct": [3], "explanation": "The ratio parts sum to 3+5=8. Each part represents 40/8=5 students. Girls = 5 parts x 5 = 25."}, {"type": "problem-solving", "data": null, "prompt": "A rectangular garden has a length of 12 meters and a width of 8 meters. If both dimensions are increased by 50%, what is the percent increase in area?", "choices": ["50%", "100%", "125%", "150%", "200%"], "correct": [2], "explanation": "Original area = 12x8=96. New dimensions are 18x12, giving a new area of 216. The increase is 216-96=120, and 120/96=125%."}, {"type": "problem-solving", "data": null, "prompt": "What is the value of x if 2^(x+1) = 32?", "choices": ["3", "4", "5", "6", "16"], "correct": [1], "explanation": "32 = 2^5, so x+1=5, giving x=4."}, {"type": "problem-solving", "data": null, "prompt": "The average (arithmetic mean) of five numbers is 18. If one of the numbers is removed, the average of the remaining four numbers is 20. What was the value of the number that was removed?", "choices": ["8", "10", "12", "14", "16"], "correct": [1], "explanation": "The sum of all 5 numbers is 5x18=90. The sum of the remaining 4 is 4x20=80. The removed number is 90-80=10."}, {"type": "problem-solving", "data": null, "prompt": "A right triangle has legs of length 6 and 8. What is the length of the hypotenuse?", "choices": ["9", "10", "11", "12", "14"], "correct": [1], "explanation": "By the Pythagorean theorem, c = sqrt(6^2+8^2) = sqrt(36+64) = sqrt(100) = 10."}, {"type": "problem-solving", "data": null, "prompt": "If it takes 4 workers 6 hours to complete a job, how many hours would it take 3 workers to complete the same job, assuming all workers work at the same constant rate?", "choices": ["4.5", "6", "7", "8", "9"], "correct": [3], "explanation": "The total work is 4 workers x 6 hours = 24 worker-hours. With 3 workers, the time needed is 24/3=8 hours."}, {"type": "problem-solving", "data": null, "prompt": "What is 15% of 15% of 400?", "choices": ["6", "9", "60", "90", "120"], "correct": [1], "explanation": "15% of 400 = 60. 15% of 60 = 9."}, {"type": "problem-solving", "data": null, "prompt": "A number is increased by 20% and then decreased by 20%. What is the net percent change?", "choices": ["0%", "-4%", "4%", "-40%", "40%"], "correct": [1], "explanation": "The combined multiplier is 1.20 x 0.80 = 0.96, which is a 4% decrease from the original."}, {"type": "problem-solving", "data": null, "prompt": "If x and y are positive integers and 2x + y = 11, what is the maximum possible value of y?", "choices": ["1", "3", "5", "9", "11"], "correct": [3], "explanation": "To maximize y, minimize x. Since x must be a positive integer, the smallest value is x=1, giving y=11-2(1)=9."}, {"type": "problem-solving", "data": null, "prompt": "The circumference of a circle is 18*pi. What is the area of the circle?", "choices": ["9*pi", "18*pi", "36*pi", "81*pi", "324*pi"], "correct": [3], "explanation": "Circumference = 2*pi*r = 18*pi, so r=9. Area = pi*r^2 = 81*pi."}, {"type": "problem-solving", "data": null, "prompt": "A car travels 240 miles using 8 gallons of gas. At this rate, how many gallons are needed to travel 420 miles?", "choices": ["12", "14", "16", "18", "20"], "correct": [1], "explanation": "The car's rate is 240/8=30 miles per gallon. 420/30=14 gallons."}, {"type": "problem-solving", "data": null, "prompt": "If the probability of rain on any given day this week is 1/4, what is the probability that it does NOT rain on a randomly chosen day?", "choices": ["1/4", "1/3", "1/2", "3/4", "4/5"], "correct": [3], "explanation": "Probabilities of complementary events sum to 1, so the probability of no rain is 1 - 1/4 = 3/4."}, {"type": "problem-solving", "data": null, "prompt": "Simplify: (3x^2y)(4xy^3).", "choices": ["7x^3y^4", "12x^3y^4", "12x^2y^3", "7x^2y^3", "12x^3y^3"], "correct": [1], "explanation": "Multiply coefficients: 3x4=12. Add exponents of like variables: x^2 x x^1 = x^3, and y^1 x y^3 = y^4. Result: 12x^3y^4."}, {"type": "problem-solving", "data": null, "prompt": "A jar contains only red and blue marbles in a ratio of 2:3. If there are 12 red marbles, how many total marbles are in the jar?", "choices": ["18", "20", "24", "28", "30"], "correct": [4], "explanation": "Since red corresponds to 2 parts and there are 12 red marbles, 1 part = 6. Total parts = 2+3=5, so total marbles = 5x6=30."}, {"type": "problem-solving", "data": null, "prompt": "What is the sum of the first 10 positive even integers?", "choices": ["55", "90", "100", "110", "120"], "correct": [3], "explanation": "The first 10 positive even integers are 2,4,...,20. Their sum is 2(1+2+...+10) = 2x55=110."}, {"type": "problem-solving", "data": null, "prompt": "If f(x) = x^2 - 3x + 2, what is f(5)?", "choices": ["7", "10", "12", "15", "22"], "correct": [2], "explanation": "f(5) = 25 - 15 + 2 = 12."}, {"type": "problem-solving", "data": null, "prompt": "A store sells notebooks for $2.50 each. If a customer buys notebooks with a $20 bill and receives $2.50 in change, how many notebooks did the customer buy?", "choices": ["5", "6", "7", "8", "9"], "correct": [2], "explanation": "The customer spent 20-2.50=$17.50. At $2.50 per notebook, 17.50/2.50=7 notebooks."}, {"type": "quantitative-comparison", "data": null, "prompt": "x is a real number.\nQuantity A: x^2\nQuantity B: x^3", "choices": ["Quantity A is greater", "Quantity B is greater", "The two quantities are equal", "The relationship cannot be determined from the given information"], "correct": [3], "explanation": "Test values: if x=2, A=4 and B=8, so B is greater. If x=-2, A=4 and B=-8, so A is greater. Since the relationship changes depending on the value of x, it cannot be determined."}, {"type": "quantitative-comparison", "data": null, "prompt": "Quantity A: 3/7\nQuantity B: 5/11", "choices": ["Quantity A is greater", "Quantity B is greater", "The two quantities are equal", "The relationship cannot be determined from the given information"], "correct": [1], "explanation": "Cross-multiply: 3x11=33 and 5x7=35. Since 35>33, 5/11 is the larger fraction, so Quantity B is greater."}, {"type": "quantitative-comparison", "data": null, "prompt": "x + y = 10 and x > y.\nQuantity A: x\nQuantity B: 5", "choices": ["Quantity A is greater", "Quantity B is greater", "The two quantities are equal", "The relationship cannot be determined from the given information"], "correct": [0], "explanation": "If x=y, both would equal 5 (since they sum to 10). Since x is strictly greater than y, x must be greater than 5, so Quantity A is greater."}, {"type": "quantitative-comparison", "data": null, "prompt": "Quantity A: (-3)^4\nQuantity B: (-4)^3", "choices": ["Quantity A is greater", "Quantity B is greater", "The two quantities are equal", "The relationship cannot be determined from the given information"], "correct": [0], "explanation": "(-3)^4 = 81, since an even exponent makes the result positive. (-4)^3 = -64, since an odd exponent keeps the result negative. 81 > -64, so Quantity A is greater."}, {"type": "quantitative-comparison", "data": null, "prompt": "The average of 4, 8, and x is 8.\nQuantity A: x\nQuantity B: 12", "choices": ["Quantity A is greater", "Quantity B is greater", "The two quantities are equal", "The relationship cannot be determined from the given information"], "correct": [2], "explanation": "If the average of 4, 8, and x is 8, their sum is 24. Since 4+8=12, x=24-12=12. The two quantities are equal."}, {"type": "quantitative-comparison", "data": null, "prompt": "Quantity A: The area of a circle with radius 3\nQuantity B: The area of a square with side 5", "choices": ["Quantity A is greater", "Quantity B is greater", "The two quantities are equal", "The relationship cannot be determined from the given information"], "correct": [0], "explanation": "Quantity A = pi(3)^2 = 9*pi, which is approximately 28.3. Quantity B = 5^2 = 25. Since 28.3 > 25, Quantity A is greater."}, {"type": "quantitative-comparison", "data": null, "prompt": "0 < x < 1.\nQuantity A: x\nQuantity B: x^2", "choices": ["Quantity A is greater", "Quantity B is greater", "The two quantities are equal", "The relationship cannot be determined from the given information"], "correct": [0], "explanation": "For any value strictly between 0 and 1, squaring makes the number smaller (for example, 0.5^2=0.25). So x is always greater than x^2 in this range, and Quantity A is greater."}, {"type": "quantitative-comparison", "data": null, "prompt": "Quantity A: The number of prime numbers between 1 and 20\nQuantity B: 8", "choices": ["Quantity A is greater", "Quantity B is greater", "The two quantities are equal", "The relationship cannot be determined from the given information"], "correct": [2], "explanation": "The primes between 1 and 20 are 2, 3, 5, 7, 11, 13, 17, and 19, a total of 8 primes. The two quantities are equal."}, {"type": "quantitative-comparison", "data": null, "prompt": "y = x^2 + 1.\nQuantity A: y\nQuantity B: 1", "choices": ["Quantity A is greater", "Quantity B is greater", "The two quantities are equal", "The relationship cannot be determined from the given information"], "correct": [3], "explanation": "Since x^2 is always greater than or equal to 0, y is always greater than or equal to 1. When x=0, the quantities are equal; for any other x, Quantity A is greater. Because the relationship is not the same in every case, it cannot be determined."}, {"type": "quantitative-comparison", "data": null, "prompt": "Quantity A: 40% of 150\nQuantity B: 150% of 40", "choices": ["Quantity A is greater", "Quantity B is greater", "The two quantities are equal", "The relationship cannot be determined from the given information"], "correct": [2], "explanation": "40% of 150 = 60, and 150% of 40 = 60. In general, a% of b always equals b% of a, so the two quantities are equal."}, {"type": "quantitative-comparison", "data": null, "prompt": "n is an integer greater than 1.\nQuantity A: n^2\nQuantity B: n", "choices": ["Quantity A is greater", "Quantity B is greater", "The two quantities are equal", "The relationship cannot be determined from the given information"], "correct": [0], "explanation": "For any integer greater than 1 (such as 2, 3, 4...), squaring the number always produces a larger result (for example, 2^2=4>2). So Quantity A is always greater."}, {"type": "quantitative-comparison", "data": null, "prompt": "Quantity A: sqrt(50) + sqrt(18)\nQuantity B: sqrt(98)", "choices": ["Quantity A is greater", "Quantity B is greater", "The two quantities are equal", "The relationship cannot be determined from the given information"], "correct": [0], "explanation": "sqrt(50)=5*sqrt(2) and sqrt(18)=3*sqrt(2), so Quantity A = 8*sqrt(2), approximately 11.3. sqrt(98)=7*sqrt(2), approximately 9.9. Quantity A is greater."}, {"type": "quantitative-comparison", "data": null, "prompt": "A jar has 5 red and 3 blue marbles. One marble is drawn at random.\nQuantity A: Probability of drawing red\nQuantity B: 5/8", "choices": ["Quantity A is greater", "Quantity B is greater", "The two quantities are equal", "The relationship cannot be determined from the given information"], "correct": [2], "explanation": "There are 8 total marbles, 5 of which are red, so the probability of drawing red is 5/8. The two quantities are equal."}, {"type": "quantitative-comparison", "data": null, "prompt": "Quantity A: The perimeter of a rectangle with length 10 and width 4\nQuantity B: The perimeter of a square with side 7", "choices": ["Quantity A is greater", "Quantity B is greater", "The two quantities are equal", "The relationship cannot be determined from the given information"], "correct": [2], "explanation": "Quantity A = 2(10+4)=28. Quantity B = 4(7)=28. The two quantities are equal."}, {"type": "quantitative-comparison", "data": null, "prompt": "x^2 = 16.\nQuantity A: x\nQuantity B: 4", "choices": ["Quantity A is greater", "Quantity B is greater", "The two quantities are equal", "The relationship cannot be determined from the given information"], "correct": [3], "explanation": "x could be 4 or -4, since both satisfy x^2=16. If x=4, the quantities are equal; if x=-4, Quantity B is greater. Because the relationship changes, it cannot be determined."}, {"type": "data-interpretation", "data": "Annual Revenue by Division (in $ millions):\nDivision A: 2021 = 40, 2022 = 48, 2023 = 54\nDivision B: 2021 = 30, 2022 = 33, 2023 = 45", "prompt": "What was the percent increase in Division B's revenue from 2021 to 2023?", "choices": ["30%", "40%", "50%", "60%", "75%"], "correct": [2], "explanation": "The increase is 45-30=15. The percent increase is 15/30 = 50%."}, {"type": "data-interpretation", "data": "Test Score Distribution (40 students total):\n90-100: 8 students\n80-89: 15 students\n70-79: 12 students\n60-69: 5 students", "prompt": "What fraction of the 40 students scored below 80?", "choices": ["5/40", "12/40", "17/40", "23/40", "27/40"], "correct": [2], "explanation": "Students scoring below 80 are those in the 70-79 range (12) plus the 60-69 range (5), totaling 17 students out of 40, or 17/40."}, {"type": "data-interpretation", "data": "Monthly Rainfall (inches):\nJan=3, Feb=2, Mar=4, Apr=5, May=6, Jun=3", "prompt": "What is the average monthly rainfall over these six months?", "choices": ["3.0", "3.5", "3.8", "4.0", "4.2"], "correct": [2], "explanation": "The total rainfall is 3+2+4+5+6+3=23 inches over 6 months. The average is 23/6, approximately 3.8 inches."}, {"type": "data-interpretation", "data": "Survey of 200 people:\nPrefer coffee = 120\nPrefer tea = 50\nPrefer neither = 30", "prompt": "What percent of respondents prefer coffee?", "choices": ["25%", "40%", "50%", "60%", "65%"], "correct": [3], "explanation": "120 out of 200 people prefer coffee. 120/200 = 60%."}, {"type": "data-interpretation", "data": "Company Employees by Department (100 total):\nEngineering=45, Sales=30, Marketing=15, Support=10", "prompt": "If the company adds 20 new employees, all to Sales, what percent of the total workforce (now 120) will Sales represent?", "choices": ["25%", "33%", "40%", "41.7%", "50%"], "correct": [3], "explanation": "After the hires, Sales has 30+20=50 employees out of a new total of 100+20=120. 50/120 is approximately 41.7%."}, {"type": "data-interpretation", "data": "Product Price History:\nQ1 = $50.00, Q2 = $55.00, Q3 = $60.50\nEach quarter, the price increased by 10% over the previous quarter.", "prompt": "What was the price in Q4, following the same 10% quarterly increase?", "choices": ["$63.00", "$65.00", "$66.55", "$70.00", "$72.00"], "correct": [2], "explanation": "Applying a 10% increase to the Q3 price: 60.50 x 1.10 = 66.55."}, {"type": "data-interpretation", "data": "Class Grade Distribution (30 students):\nA=6, B=12, C=9, D=2, F=1", "prompt": "What is the ratio of students who received a B to students who received a C?", "choices": ["2:3", "3:4", "4:3", "3:2", "5:3"], "correct": [2], "explanation": "The ratio of B students to C students is 12:9, which simplifies (dividing both by 3) to 4:3."}, {"type": "data-interpretation", "data": "Website Visitors by Source (9,000 total):\nSearch=4,000, Social=2,500, Direct=1,500, Referral=1,000", "prompt": "Approximately what percent of visitors came from Search or Social combined?", "choices": ["44%", "56%", "65%", "72%", "72.2%"], "correct": [4], "explanation": "Search plus Social is 4,000+2,500=6,500. 6,500/9,000 is approximately 72.2%."}, {"type": "data-interpretation", "data": "Savings Account Balance:\nStart = $1,000\nYear 1: +$200\nYear 2: -$50\nYear 3: +$150", "prompt": "What was the balance at the end of Year 3?", "choices": ["$1,100", "$1,200", "$1,250", "$1,300", "$1,400"], "correct": [3], "explanation": "1,000 + 200 - 50 + 150 = 1,300."}, {"type": "data-interpretation", "data": "Fruit Sold at Market, in pounds (400 total):\nApples=120, Oranges=90, Bananas=150, Grapes=40", "prompt": "Bananas accounted for what fraction of total fruit sold?", "choices": ["3/10", "3/8", "2/5", "3/5", "1/2"], "correct": [1], "explanation": "Bananas were 150 out of 400 total pounds. 150/400 simplifies to 3/8."}];
